const r=$input.first()?.json??{};
if(Number(r.code)!==0) throw new Error('TPLUS_BOM_COMMAND_EXIT_FAILED');
const lines=String(r.stdout??'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);
let result;
try{result=JSON.parse([...lines].reverse().find(s=>s.startsWith('{'))??'');}catch{throw new Error('TPLUS_BOM_RESULT_INVALID');}
if(result.status!=='SUCCESS'||result.mode!=='RECONCILE'||!Array.isArray(result.sources)||result.sources.length!==2)throw new Error('TPLUS_BOM_RESULT_FAILED');
for(const key of ['tplus-kejia','tplus-kainan']){const s=result.sources.filter(s=>s.source===key);if(s.length!==1||s[0].status!=='SUCCESS'||s[0].sourceVerified!==true||!s[0].activeGeneration||!Number.isInteger(s[0].scanned)||!Number.isInteger(s[0].valid))throw new Error('TPLUS_BOM_GENERATION_NOT_VERIFIED');}
return [{json:result}];
